package com.logismart;

import com.sun.net.httpserver.HttpServer;
import java.io.*;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

/** Small dependency-free Java HTTP server serving a web dashboard and JSON results. */
public class App {
    private static final Path DATA = Path.of(System.getProperty("data.dir", "data"));
    public static void main(String[] args) throws Exception {
        int port = Integer.parseInt(System.getProperty("port", "8080"));
        HttpServer server = HttpServer.create(new InetSocketAddress(port), 0);
        server.createContext("/", ex -> { byte[] b = html().getBytes(StandardCharsets.UTF_8); ex.getResponseHeaders().set("Content-Type","text/html; charset=utf-8"); ex.sendResponseHeaders(200,b.length); try(OutputStream os=ex.getResponseBody()){os.write(b);} });
        server.createContext("/api/optimize", ex -> { try { DeliveryOptimizer.Result r = new DeliveryOptimizer().run(DATA); String json=toJson(r); byte[] b=json.getBytes(StandardCharsets.UTF_8); ex.getResponseHeaders().set("Content-Type","application/json; charset=utf-8"); ex.sendResponseHeaders(200,b.length); try(OutputStream os=ex.getResponseBody()){os.write(b);} } catch(Exception e) { byte[] b=("{\"error\":\""+escape(e.getMessage())+"\"}").getBytes(StandardCharsets.UTF_8); ex.getResponseHeaders().set("Content-Type","application/json; charset=utf-8"); ex.sendResponseHeaders(500,b.length); try(OutputStream os=ex.getResponseBody()){os.write(b);} } });
        server.start(); System.out.println("Smart Delivery prototype running at http://localhost:"+port); System.out.println("Data directory: "+DATA.toAbsolutePath());
    }
    private static String toJson(DeliveryOptimizer.Result r) {
        StringBuilder s=new StringBuilder("{\"orders\":").append(r.orders()).append(",\"allocated\":").append(r.allocated()).append(",\"baselineKm\":").append(r.baselineKm()).append(",\"optimizedKm\":").append(r.optimizedKm()).append(",\"reductionPercent\":").append(String.format(Locale.US,"%.2f",r.reductionPercent())).append(",\"plans\":[");
        for(int i=0;i<r.plans().size();i++){var p=r.plans().get(i);if(i>0)s.append(',');s.append("{\"vehicle\":\"").append(escape(p.vehicleId())).append("\",\"load\":").append(p.load()).append(",\"capacity\":").append(p.capacity()).append(",\"baselineRoute\":\"").append(escape(String.join(" → ",p.baselineRoute()))).append("\",\"optimizedRoute\":\"").append(escape(String.join(" → ",p.optimizedRoute()))).append("\",\"baselineKm\":").append(p.baselineKm()).append(",\"optimizedKm\":").append(p.optimizedKm()).append('}');}
        s.append("],\"warnings\":[");for(int i=0;i<r.warnings().size();i++){if(i>0)s.append(',');s.append('\"').append(escape(r.warnings().get(i))).append('\"');}return s.append("]}").toString();
    }
    private static String escape(String x){return x==null?"error":x.replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ").replace("\r"," ");}
    private static String html(){return """
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Smart Delivery Route Optimizer</title><style>
:root{font-family:Arial,sans-serif;color:#172033;background:#f4f7fb}body{margin:0}.hero{background:#102a43;color:white;padding:28px max(20px,calc((100% - 1050px)/2))}.hero p{color:#d9e7f5}.wrap{max-width:1050px;margin:24px auto;padding:0 18px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.card,section{background:white;border:1px solid #e1e8f0;border-radius:12px;padding:18px;box-shadow:0 3px 12px #102a430b}.metric{font-size:28px;font-weight:700;margin:8px 0}.muted{color:#65758b;font-size:13px}.btn{background:#087e8b;color:white;border:0;border-radius:8px;padding:12px 18px;font-weight:700;cursor:pointer}.btn:hover{background:#066570}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e5ebf2;font-size:14px}th{background:#f1f5f9}.notice{margin:14px 0;padding:12px;background:#fff8e6;border:1px solid #f0d995;border-radius:8px;color:#6d5310}footer{color:#64748b;font-size:12px;padding:24px 0}</style></head><body>
<div class="hero"><div style="max-width:1050px;margin:auto"><h1>Smart Delivery Route &amp; Resource Optimization</h1><p>Minor Project · MSDS-MINOR-OPT-001 · Student: Dhirender Pratap Singh</p></div></div><main class="wrap"><div class="notice"><b>Sample-data notice:</b> This prototype uses synthetic example CSV files, not official operational data. Distances are estimates from the sample matrix.</div><section><h2>Run optimization</h2><p class="muted">The app assigns high-priority orders first while respecting vehicle capacity/type, then uses a nearest-neighbour route heuristic. Routes return to depot A.</p><button class="btn" onclick="run()">Run Optimization</button><span id="status" class="muted" style="margin-left:12px">Ready</span></section><div class="cards" style="margin-top:16px"><div class="card"><div class="muted">Orders allocated</div><div class="metric" id="alloc">—</div></div><div class="card"><div class="muted">Baseline distance</div><div class="metric" id="base">—</div><div class="muted">km, return to depot</div></div><div class="card"><div class="muted">Optimized distance</div><div class="metric" id="opt">—</div><div class="muted">km, return to depot</div></div><div class="card"><div class="muted">Distance reduction</div><div class="metric" id="reduction">—</div><div class="muted">relative to baseline</div></div></div><section style="margin-top:16px"><h2>Vehicle route comparison</h2><div id="table">Click “Run Optimization” to calculate results.</div></section><section style="margin-top:16px"><h2>Validation / warnings</h2><ul id="warnings"><li>Not run yet.</li></ul></section><footer>Educational prototype · Java HTTP server · CSV inputs · Nearest-neighbour heuristic · Not a production dispatch system.</footer></main><script>
async function run(){document.getElementById('status').textContent='Calculating…';try{const res=await fetch('/api/optimize');const d=await res.json();if(!res.ok)throw new Error(d.error||'Request failed');document.getElementById('alloc').textContent=d.allocated+' / '+d.orders;document.getElementById('base').textContent=d.baselineKm+' km';document.getElementById('opt').textContent=d.optimizedKm+' km';document.getElementById('reduction').textContent=d.reductionPercent+'%';let rows=d.plans.map(p=>`<tr><td>${p.vehicle}</td><td>${p.load} / ${p.capacity}</td><td>A → ${p.baselineRoute||'—'} → A</td><td>${p.baselineKm} km</td><td>A → ${p.optimizedRoute||'—'} → A</td><td>${p.optimizedKm} km</td></tr>`).join('');document.getElementById('table').innerHTML=`<table><thead><tr><th>Vehicle</th><th>Load / capacity</th><th>Baseline route</th><th>Baseline</th><th>Optimized route</th><th>Optimized</th></tr></thead><tbody>${rows}</tbody></table>`;document.getElementById('warnings').innerHTML=d.warnings.length?d.warnings.map(w=>`<li>${w}</li>`).join(''):'<li>No validation warnings for this sample run.</li>';document.getElementById('status').textContent='Completed successfully';}catch(e){document.getElementById('status').textContent='Error: '+e.message;}}
</script></body></html>
""";}
}
